// Updating Nookstacks from inside Nookstacks.
//
// The desktop app cannot be reinstalled by the browser build, so it does it
// itself: read a small manifest published beside the release assets, compare
// versions, download the installer for this platform, check it against the
// sha256 in that manifest, then hand it to the OS and exit.
//
// No signing key is involved. The manifest is generated by the release job from
// the artifacts it just built, and both it and the installers are served by
// GitHub over TLS from the same release — so the trust anchor is the release
// itself, not a second key somebody has to keep safe.

use std::collections::HashMap;
use std::fs::{self, File};
use std::io::{Read, Write};
use std::path::{Path, PathBuf};
use std::time::Duration;

use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use tauri::Emitter;

pub const MANIFEST: &str =
    "https://github.com/OleMurpho/nookstacks/releases/latest/download/latest.json";

#[derive(Deserialize, Serialize, Clone, Debug)]
pub struct Asset {
    pub url: String,
    pub sha256: String,
    #[serde(default)]
    pub size: u64,
}

#[derive(Deserialize, Serialize, Clone, Debug)]
pub struct Manifest {
    pub version: String,
    #[serde(default)]
    pub notes: String,
    #[serde(default)]
    pub assets: HashMap<String, Asset>,
}

#[derive(Serialize, Clone, Debug)]
pub struct Check {
    pub current: String,
    pub latest: Option<String>,
    pub newer: bool,
    pub notes: String,
    pub platform: String,
    pub size: u64,
}

pub fn current_version() -> String {
    env!("CARGO_PKG_VERSION").to_string()
}

/// Which asset name this build wants. Windows installs come as the NSIS setup,
/// Linux as the AppImage, because both can be run without root.
pub fn platform_key() -> String {
    if cfg!(target_os = "windows") {
        "windows-x86_64".into()
    } else if cfg!(target_os = "linux") {
        "linux-x86_64".into()
    } else {
        "unsupported".into()
    }
}

fn agent() -> ureq::Agent {
    ureq::AgentBuilder::new()
        .timeout_connect(Duration::from_secs(10))
        .timeout_read(Duration::from_secs(60))
        .user_agent(concat!("Nookstacks/", env!("CARGO_PKG_VERSION")))
        .build()
}

/// 0.2.1 is newer than 0.2.0; 0.10.0 is newer than 0.9.9; a pre-release suffix
/// is ignored, because the manifest never offers one.
pub fn parse_version(v: &str) -> Vec<u64> {
    v.trim()
        .trim_start_matches('v')
        .split('-')
        .next()
        .unwrap_or("")
        .split('.')
        .map(|p| p.parse::<u64>().unwrap_or(0))
        .collect()
}

pub fn is_newer(latest: &str, current: &str) -> bool {
    let a = parse_version(latest);
    let b = parse_version(current);
    for i in 0..a.len().max(b.len()) {
        let x = *a.get(i).unwrap_or(&0);
        let y = *b.get(i).unwrap_or(&0);
        if x != y {
            return x > y;
        }
    }
    false
}

/// Where the manifest lives. NOOKSTACKS_UPDATE_URL exists so a test build (or
/// a fork) can point at its own release without a rebuild of this constant.
pub fn manifest_url() -> String {
    std::env::var("NOOKSTACKS_UPDATE_URL")
        .ok()
        .filter(|s| !s.trim().is_empty())
        .unwrap_or_else(|| MANIFEST.to_string())
}

pub fn fetch_manifest() -> Result<Manifest, String> {
    let res = agent()
        .get(&manifest_url())
        .call()
        .map_err(|e| format!("could not reach the release server ({e})"))?;
    let body = res.into_string().map_err(|e| e.to_string())?;
    serde_json::from_str(&body).map_err(|e| format!("manifest is not readable ({e})"))
}

pub fn check() -> Result<Check, String> {
    let current = current_version();
    let m = fetch_manifest()?;
    let key = platform_key();
    let asset = m.assets.get(&key);
    Ok(Check {
        newer: is_newer(&m.version, &current),
        latest: Some(m.version.clone()),
        notes: m.notes.clone(),
        platform: key,
        size: asset.map(|a| a.size).unwrap_or(0),
        current,
    })
}

fn temp_dir() -> PathBuf {
    std::env::temp_dir().join("nookstacks-update")
}

/// Stream the installer to disk, hashing as it arrives. `progress` gets 0..=100.
pub fn download(asset: &Asset, progress: &dyn Fn(u8)) -> Result<PathBuf, String> {
    let dir = temp_dir();
    fs::create_dir_all(&dir).map_err(|e| e.to_string())?;
    let name = asset
        .url
        .rsplit('/')
        .next()
        .unwrap_or("nookstacks-update.exe")
        .split('?')
        .next()
        .unwrap_or("nookstacks-update.exe");
    let path = dir.join(name);

    let res = agent()
        .get(&asset.url)
        .call()
        .map_err(|e| format!("download failed ({e})"))?;
    let total = res
        .header("content-length")
        .and_then(|v| v.parse::<u64>().ok())
        .unwrap_or(asset.size);
    let mut reader = res.into_reader();
    let mut file = File::create(&path).map_err(|e| e.to_string())?;
    let mut hasher = Sha256::new();
    let mut buf = [0u8; 64 * 1024];
    let mut done: u64 = 0;
    let mut last = 255u8;
    loop {
        let n = reader.read(&mut buf).map_err(|e| e.to_string())?;
        if n == 0 {
            break;
        }
        file.write_all(&buf[..n]).map_err(|e| e.to_string())?;
        hasher.update(&buf[..n]);
        done += n as u64;
        if total > 0 {
            let pct = ((done * 100) / total).min(100) as u8;
            if pct != last {
                last = pct;
                progress(pct);
            }
        }
    }
    file.flush().map_err(|e| e.to_string())?;
    drop(file);

    let got = format!("{:x}", hasher.finalize());
    if !asset.sha256.is_empty() && got != asset.sha256.to_lowercase() {
        let _ = fs::remove_file(&path);
        return Err(format!(
            "the download did not match its checksum (got {got}, expected {})",
            asset.sha256
        ));
    }
    progress(100);
    Ok(path)
}

fn log_line(path: &Path, msg: &str) {
    let stamp = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);
    if let Ok(mut f) = fs::OpenOptions::new().create(true).append(true).open(path) {
        let _ = writeln!(f, "{stamp} {msg}");
    }
}

pub fn log_path() -> PathBuf {
    crate::vault::vault_dir()
        .parent()
        .map(|p| p.join("updater.log"))
        .unwrap_or_else(|| PathBuf::from("nookstacks-updater.log"))
}

/// Run the installer. Windows: the NSIS setup for this user, silently, then
/// reopen the app once it exits. Linux: replace the AppImage in place.
#[cfg(target_os = "windows")]
pub fn launch_installer(installer: &Path) -> Result<(), String> {
    use std::os::windows::process::CommandExt;

    let app = std::env::current_exe().map_err(|e| e.to_string())?;
    let script = temp_dir().join("apply-update.cmd");
    let body = format!(
        "@echo off\r\n\
         ping -n 2 127.0.0.1 >nul\r\n\
         start /wait \"\" \"{}\" /S\r\n\
         start \"\" \"{}\"\r\n",
        installer.display(),
        app.display()
    );
    fs::write(&script, body).map_err(|e| e.to_string())?;
    // DETACHED_PROCESS | CREATE_NO_WINDOW: the helper outlives us quietly
    std::process::Command::new("cmd")
        .arg("/C")
        .arg(&script)
        .creation_flags(0x0000_0008 | 0x0800_0000)
        .spawn()
        .map_err(|e| format!("could not start the installer ({e})"))?;
    Ok(())
}

#[cfg(target_os = "linux")]
pub fn launch_installer(installer: &Path) -> Result<(), String> {
    // An AppImage can replace itself; a package install cannot without root.
    if let Ok(here) = std::env::var("APPIMAGE") {
        let target = PathBuf::from(here);
        let staged = target.with_extension("new");
        fs::copy(installer, &staged).map_err(|e| e.to_string())?;
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            fs::set_permissions(&staged, fs::Permissions::from_mode(0o755))
                .map_err(|e| e.to_string())?;
        }
        fs::rename(&staged, &target).map_err(|e| e.to_string())?;
        let _ = std::process::Command::new(&target).spawn();
        return Ok(());
    }
    Err("this build was installed by a package manager; download the new .deb or .rpm from the release page".into())
}

#[cfg(not(any(target_os = "windows", target_os = "linux")))]
pub fn launch_installer(_installer: &Path) -> Result<(), String> {
    Err("this platform updates from the release page".into())
}


/// Keep a copy of the board before an installer runs.
///
/// The updater itself never writes to the vault, and the per-user installer only
/// replaces program files. Both of those are assumptions, though, and a board is
/// not something to lose because an assumption stopped being true. This costs a
/// few kilobytes and makes the worst case recoverable.
pub fn backup_vault(reason: &str) -> Option<PathBuf> {
    let vault = crate::vault::vault_dir();
    let state = vault.join("state.json");
    if !state.is_file() {
        return None;
    }
    let dir = vault.parent()?.join("backups");
    fs::create_dir_all(&dir).ok()?;
    let stamp = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);
    let dest = dir.join(format!("state-{reason}-{stamp}.json"));
    fs::copy(&state, &dest).ok()?;

    // the newest five are enough to undo a bad week
    let mut kept: Vec<PathBuf> = fs::read_dir(&dir)
        .ok()?
        .filter_map(|e| e.ok().map(|e| e.path()))
        .filter(|p| p.extension().map(|x| x == "json").unwrap_or(false))
        .collect();
    kept.sort();
    while kept.len() > 5 {
        let old = kept.remove(0);
        let _ = fs::remove_file(old);
    }
    Some(dest)
}

/// Headless path used by `nookstacks --update-now` and by the release check:
/// check, download, verify, launch, and report each step to a log file.
pub fn install_blocking() -> Result<String, String> {
    let log = log_path();
    log_line(&log, &format!("check {} (current {})", manifest_url(), current_version()));
    let m = fetch_manifest()?;
    log_line(&log, &format!("server has {}", m.version));
    if !is_newer(&m.version, &current_version()) {
        log_line(&log, "already up to date");
        return Ok(format!("{} is the newest version", current_version()));
    }
    let key = platform_key();
    let asset = m
        .assets
        .get(&key)
        .ok_or_else(|| format!("release {} has no build for {key}", m.version))?
        .clone();
    log_line(&log, &format!("downloading {} ({} bytes)", asset.url, asset.size));
    let path = download(&asset, &|p| {
        if p % 10 == 0 {
            log_line(&log, &format!("download {p}%"));
        }
    })?;
    log_line(&log, &format!("verified sha256, installer at {}", path.display()));
    match backup_vault(&format!("pre-{}", m.version)) {
        Some(p) => log_line(&log, &format!("board backed up to {}", p.display())),
        None => log_line(&log, "no board to back up"),
    }
    launch_installer(&path)?;
    log_line(&log, "installer started, exiting");
    Ok(format!("installing {}", m.version))
}

// ---------------------------------------------------------------- commands

#[derive(Serialize)]
pub struct Installed {
    version: String,
    platform: String,
}

#[tauri::command]
pub fn update_state() -> Installed {
    Installed {
        version: current_version(),
        platform: platform_key(),
    }
}

#[tauri::command]
pub async fn update_check() -> Result<Check, String> {
    tauri::async_runtime::spawn_blocking(check)
        .await
        .map_err(|e| e.to_string())?
}

#[tauri::command]
pub async fn update_install(app: tauri::AppHandle) -> Result<(), String> {
    let handle = app.clone();
    tauri::async_runtime::spawn_blocking(move || -> Result<(), String> {
        let m = fetch_manifest()?;
        if !is_newer(&m.version, &current_version()) {
            return Err("already up to date".into());
        }
        let key = platform_key();
        let asset = m
            .assets
            .get(&key)
            .ok_or_else(|| format!("release {} has no build for {key}", m.version))?
            .clone();
        let path = download(&asset, &|p| {
            let _ = handle.emit("update:progress", p);
        })?;
        let _ = backup_vault(&format!("pre-{}", m.version));
        launch_installer(&path)?;
        let _ = handle.emit("update:installing", m.version.clone());
        std::thread::sleep(Duration::from_millis(400));
        handle.exit(0);
        Ok(())
    })
    .await
    .map_err(|e| e.to_string())?
}
